 folderitems=[('Notes','annotated reading','notebook','python/'),('Notebooks','working examples','code','library/#notebooks'),('References','the technical shelf','book-open','Research/'),('Tools','developer essentials','toolbox','Tools_Compilation/'),('Study plan','connect the foundations','map-trifold','Programming_Interview_Study_Plan/')]
